// search/parse.ts - the gate between an untrusted JSON blob and the search surface. Same contract
// as `snapshot/parse.ts`: closed (an unrecognised property is an error, never a silent drop),
// exhaustive (every problem in one pass) and positional (each diagnostic names the failing JSON
// pointer), because a search index is generated by somebody's script against somebody's bucket and
// is typically enormous - "invalid index" tells the holder of a 200,000-line file nothing at all.
//
// Hand-written rather than a bundled JSON-Schema runtime: the package ships zero runtime
// dependencies, `schema/dataset-tree-search-index-v1.schema.json` is published beside it for build
// tooling, and `tests/schema-parity.test.ts` asserts the two never disagree. Reachable only from
// `@freva-org/dataset-tree/search-index`, so a consumer with an already-validated index, or none at
// all, does not pay for it.

import type {
  DatasetTreeNodeKind,
  DatasetTreeSearchAncestor,
  DatasetTreeSearchIndex,
  DatasetTreeSearchIndexEntry,
} from "../types.js";

/** One thing wrong with the input, and exactly where. */
export interface DatasetTreeSearchIndexDiagnostic {
  /** RFC 6901 JSON pointer, e.g. `/entries/12/kind`. `""` is the document itself. */
  path: string;
  /** Stable machine-readable reason. */
  code:
    | "not-an-object"
    | "unknown-property"
    | "missing-property"
    | "invalid-type"
    | "invalid-value"
    | "empty-string"
    | "duplicate-id";
  message: string;
}

/** Thrown by {@link parseDatasetTreeSearchIndexV1}. Carries every diagnostic, not just the first. */
export class DatasetTreeSearchIndexError extends Error {
  readonly diagnostics: readonly DatasetTreeSearchIndexDiagnostic[];

  constructor(diagnostics: readonly DatasetTreeSearchIndexDiagnostic[]) {
    const head = diagnostics
      .slice(0, 5)
      .map((d) => `  ${d.path || "/"}: ${d.message}`)
      .join("\n");
    const rest = diagnostics.length > 5 ? `\n  … and ${diagnostics.length - 5} more` : "";
    super(
      `dataset-tree search index is not valid (${diagnostics.length} problems):\n${head}${rest}`,
    );
    this.name = "DatasetTreeSearchIndexError";
    this.diagnostics = diagnostics;
  }
}

const KINDS: readonly DatasetTreeNodeKind[] = ["collection", "directory", "dataset", "file"];

const DOCUMENT_PROPERTIES = new Set([
  "schemaVersion",
  "generatedAt",
  "source",
  "complete",
  "entries",
]);
const ENTRY_PROPERTIES = new Set([
  "id",
  "kind",
  "name",
  "title",
  "path",
  "size",
  "modifiedAt",
  "ancestors",
]);
const ANCESTOR_PROPERTIES = new Set(["id", "name", "title", "path"]);

/** RFC 6901 escaping, so a key containing `/` or `~` still produces a usable pointer. */
function pointer(base: string, key: string | number): string {
  const token = String(key).replace(/~/g, "~0").replace(/\//g, "~1");
  return `${base}/${token}`;
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

class Collector {
  readonly diagnostics: DatasetTreeSearchIndexDiagnostic[] = [];

  add(path: string, code: DatasetTreeSearchIndexDiagnostic["code"], message: string): void {
    this.diagnostics.push({ path, code, message });
  }

  requiredString(container: Record<string, unknown>, path: string, key: string): string | null {
    const value = container[key];
    if (value === undefined) {
      this.add(pointer(path, key), "missing-property", `\`${key}\` is required`);
      return null;
    }
    if (typeof value !== "string") {
      this.add(pointer(path, key), "invalid-type", `\`${key}\` must be a string`);
      return null;
    }
    if (value.length === 0) {
      this.add(pointer(path, key), "empty-string", `\`${key}\` must not be empty`);
      return null;
    }
    return value;
  }

  optionalString(
    container: Record<string, unknown>,
    path: string,
    key: string,
  ): string | undefined {
    const value = container[key];
    if (value === undefined) return undefined;
    if (typeof value !== "string") {
      this.add(pointer(path, key), "invalid-type", `\`${key}\` must be a string`);
      return undefined;
    }
    return value;
  }

  optionalSize(container: Record<string, unknown>, path: string, key: string): number | undefined {
    const value = container[key];
    if (value === undefined) return undefined;
    if (typeof value !== "number" || !Number.isFinite(value)) {
      this.add(pointer(path, key), "invalid-type", `\`${key}\` must be a finite number`);
      return undefined;
    }
    if (value < 0) {
      this.add(pointer(path, key), "invalid-value", `\`${key}\` must not be negative`);
      return undefined;
    }
    return value;
  }

  closed(container: Record<string, unknown>, path: string, allowed: ReadonlySet<string>): void {
    for (const key of Object.keys(container)) {
      if (allowed.has(key)) continue;
      this.add(pointer(path, key), "unknown-property", `unknown property \`${key}\``);
    }
  }
}

function parseAncestors(
  collector: Collector,
  raw: unknown,
  path: string,
): readonly DatasetTreeSearchAncestor[] | undefined {
  if (raw === undefined) return undefined;
  if (!Array.isArray(raw)) {
    collector.add(path, "invalid-type", "`ancestors` must be an array");
    return undefined;
  }
  const out: DatasetTreeSearchAncestor[] = [];
  raw.forEach((entry, index) => {
    const entryPath = pointer(path, index);
    if (!isPlainObject(entry)) {
      collector.add(entryPath, "not-an-object", "each ancestor must be an object");
      return;
    }
    collector.closed(entry, entryPath, ANCESTOR_PROPERTIES);
    const id = collector.requiredString(entry, entryPath, "id");
    const name = collector.requiredString(entry, entryPath, "name");
    const title = collector.optionalString(entry, entryPath, "title");
    const ancestorPath = collector.optionalString(entry, entryPath, "path");
    if (id === null || name === null) return;
    const ancestor: Record<string, unknown> = { id, name };
    if (title !== undefined) ancestor.title = title;
    if (ancestorPath !== undefined) ancestor.path = ancestorPath;
    out.push(Object.freeze(ancestor) as unknown as DatasetTreeSearchAncestor);
  });
  return Object.freeze(out);
}

function parseEntry(
  collector: Collector,
  raw: unknown,
  path: string,
  seen: Map<string, string>,
): DatasetTreeSearchIndexEntry | null {
  if (!isPlainObject(raw)) {
    collector.add(path, "not-an-object", "each entry must be an object");
    return null;
  }
  collector.closed(raw, path, ENTRY_PROPERTIES);

  const id = collector.requiredString(raw, path, "id");
  if (id !== null) {
    const first = seen.get(id);
    if (first !== undefined) {
      // Rejected, not merged or renamed: identity deduplicates a result against a loaded node and
      // is what a consumer's `onNavigate` receives, so two entries claiming one id leave "which one
      // did the reader click?" unanswerable - a question for the build that produced the file.
      collector.add(
        pointer(path, "id"),
        "duplicate-id",
        `duplicate id \`${id}\` (already used at ${first})`,
      );
    } else {
      seen.set(id, path);
    }
  }

  const name = collector.requiredString(raw, path, "name");

  let kind: DatasetTreeNodeKind | null = null;
  const rawKind = raw.kind;
  if (rawKind === undefined) {
    collector.add(pointer(path, "kind"), "missing-property", "`kind` is required");
  } else if (typeof rawKind !== "string" || !KINDS.includes(rawKind as DatasetTreeNodeKind)) {
    collector.add(
      pointer(path, "kind"),
      "invalid-value",
      `\`kind\` must be one of ${KINDS.join(", ")}`,
    );
  } else {
    kind = rawKind as DatasetTreeNodeKind;
  }

  const title = collector.optionalString(raw, path, "title");
  const entryPath = collector.optionalString(raw, path, "path");
  const modifiedAt = collector.optionalString(raw, path, "modifiedAt");
  const size = collector.optionalSize(raw, path, "size");
  const ancestors = parseAncestors(collector, raw.ancestors, pointer(path, "ancestors"));

  if (id === null || name === null || kind === null) return null;

  const entry: Record<string, unknown> = { id, kind, name };
  if (title !== undefined) entry.title = title;
  if (entryPath !== undefined) entry.path = entryPath;
  if (size !== undefined) entry.size = size;
  if (modifiedAt !== undefined) entry.modifiedAt = modifiedAt;
  if (ancestors !== undefined) entry.ancestors = ancestors;
  return Object.freeze(entry) as unknown as DatasetTreeSearchIndexEntry;
}

/**
 * Validate an already-loaded value as a `dataset-tree-search-index-v1` document. Takes a JavaScript
 * value, not a URL and not a string: fetching is the host's job - this package makes no network
 * request for an index - so a portal can inline it, read it from a build artifact or receive it
 * from wherever it likes, and no network path here has to be secured. Order is preserved exactly as
 * declared: ranking decides the order results are shown in, and the document's own order is the
 * final tie-break's input.
 *
 * @throws {DatasetTreeSearchIndexError} with every diagnostic found, if the value is not valid.
 */
export function parseDatasetTreeSearchIndexV1(input: unknown): DatasetTreeSearchIndex {
  const collector = new Collector();

  if (!isPlainObject(input)) {
    throw new DatasetTreeSearchIndexError([
      { path: "", code: "not-an-object", message: "the search index must be an object" },
    ]);
  }

  collector.closed(input, "", DOCUMENT_PROPERTIES);

  const version = input.schemaVersion;
  if (version === undefined) {
    collector.add("/schemaVersion", "missing-property", "`schemaVersion` is required");
  } else if (version !== 1) {
    collector.add(
      "/schemaVersion",
      "invalid-value",
      `this build understands \`schemaVersion: 1\` only (got ${JSON.stringify(version)})`,
    );
  }

  // `complete` is required rather than defaulted: it is the one field whose value decides what the
  // interface promises a reader, and a default would be a claim the component made up - `false`
  // quietly downgrading honest complete indexes, `true` quietly laundering partial ones.
  let complete = false;
  const rawComplete = input.complete;
  if (rawComplete === undefined) {
    collector.add("/complete", "missing-property", "`complete` is required");
  } else if (typeof rawComplete !== "boolean") {
    collector.add("/complete", "invalid-type", "`complete` must be true or false");
  } else {
    complete = rawComplete;
  }

  const entries: DatasetTreeSearchIndexEntry[] = [];
  if (input.entries === undefined) {
    collector.add("/entries", "missing-property", "`entries` is required");
  } else if (!Array.isArray(input.entries)) {
    collector.add("/entries", "invalid-type", "`entries` must be an array");
  } else {
    const seen = new Map<string, string>();
    input.entries.forEach((raw, index) => {
      const parsed = parseEntry(collector, raw, pointer("/entries", index), seen);
      if (parsed) entries.push(parsed);
    });
  }

  const generatedAt = collector.optionalString(input, "", "generatedAt");
  const sourceLabel = collector.optionalString(input, "", "source");

  if (collector.diagnostics.length > 0) {
    throw new DatasetTreeSearchIndexError(collector.diagnostics);
  }

  const document: Record<string, unknown> = { schemaVersion: 1 as const };
  if (generatedAt !== undefined) document.generatedAt = generatedAt;
  if (sourceLabel !== undefined) document.source = sourceLabel;
  document.complete = complete;
  document.entries = Object.freeze(entries);
  return Object.freeze(document) as unknown as DatasetTreeSearchIndex;
}
